// Package mcpinstructions lets a design declare the instructions that an MCP
// server generated by goa-ai returns, which goa-ai v0.90.0 cannot declare.
// Clients may add the instructions to the system prompt of the model, where the
// model sees them before it loads deferred tools and reads their descriptions.
//
// Importing the package registers a Goa plugin that runs after the MCP plugin
// of goa-ai. It adds the optional instructions field of MCP 2026-07-28 to the
// server/discover result, which the legacy initialize result embeds, and writes
// the declared text into the generated ServerDiscover. Remove the package once
// goa-ai declares instructions itself.
package mcpinstructions

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"strings"

	mcpexpr "goa.design/goa-ai/expr/mcp"
	"goa.design/goa/v3/eval"
)

type (
	// RootExpr holds the instructions declared for each MCP server.
	RootExpr struct {
		// Servers maps each MCP server to its instructions.
		Servers map[*mcpexpr.MCPExpr]*InstructionsExpr
	}

	// InstructionsExpr is the text that one MCP server returns as its
	// instructions.
	InstructionsExpr struct {
		// MCP is the server that returns the instructions.
		MCP *mcpexpr.MCPExpr
		// Text is returned to clients as is.
		Text string
	}
)

// Root holds the instructions declared by the design being evaluated.
var Root *RootExpr

func init() {
	Root = NewRoot()
	if err := eval.Register(Root); err != nil {
		panic(err)
	}
}

// Instructions sets the instructions that the MCP server returns in
// server/discover and initialize. Clients may add them to the system prompt of
// the model, so they should tell what the server holds and when to use its
// tools, and not repeat the tool descriptions.
//
// Instructions must appear in the design function of MCP, at most once:
//
//	MCP("notes", "1.0.0", func() {
//	    mcpinstructions.Instructions("Search the notes before answering ...")
//	})
func Instructions(text string) {
	m, ok := eval.Current().(*mcpexpr.MCPExpr)
	if !ok {
		eval.IncompatibleDSL()
		return
	}
	if strings.TrimSpace(text) == "" {
		eval.ReportError("instructions of MCP server %q are empty", m.Name)
		return
	}
	if _, ok := Root.Servers[m]; ok {
		eval.ReportError("instructions of MCP server %q are declared more than once", m.Name)
		return
	}
	Root.Servers[m] = &InstructionsExpr{MCP: m, Text: text}
}

// NewRoot returns a root without instructions.
func NewRoot() *RootExpr {
	return &RootExpr{Servers: make(map[*mcpexpr.MCPExpr]*InstructionsExpr)}
}

// EvalName returns the name used in error messages.
func (r *RootExpr) EvalName() string {
	return "MCP instructions plugin"
}

// DependsOn evaluates the MCP servers of goa-ai first.
func (r *RootExpr) DependsOn() []eval.Root {
	return []eval.Root{mcpexpr.Root}
}

// Packages returns the package of the DSL for error reporting.
func (r *RootExpr) Packages() []string {
	return []string{"github.com/ikawaha/goaaiplugins/mcpinstructions"}
}

// WalkSets walks the instructions in the order of their services.
func (r *RootExpr) WalkSets(walk eval.SetWalker) {
	var set eval.ExpressionSet
	for _, e := range r.sorted() {
		set = append(set, e)
	}
	walk(set)
}

// EvalName returns the name used in error messages.
func (e *InstructionsExpr) EvalName() string {
	return fmt.Sprintf("instructions of MCP server %q", e.MCP.Name)
}

// sorted returns the instructions in the order of the names of their services,
// so that generation and its errors do not depend on map order.
func (r *RootExpr) sorted() []*InstructionsExpr {
	return slices.SortedFunc(maps.Values(r.Servers), func(a, b *InstructionsExpr) int {
		return cmp.Compare(a.MCP.Service.Name, b.MCP.Service.Name)
	})
}
